'use strict';
// All workflows below are local demonstrations. No email, calendar invite or call is sent.
let opsInboxQuery='';
pickerRows=function(tier){
  const q=stationPickerQuery.trim().toLowerCase(),rows=q?stations.filter(s=>`${s.city} ${s.state} ${s.name} ${s.id}`.toLowerCase().includes(q)).slice(0,20):[...chosenStations.map(journeyStation).filter(Boolean),...stations.filter(s=>!chosenStations.includes(s.id)).slice(0,6)];
  return rows.length?rows.map(s=>{const p=stationPhoto(s),chosen=chosenStations.includes(s.id);return `<label class="picker-row ops-picker-row ${chosen?'ops-picker-selected':''}"><input type="checkbox" data-pick-station="${s.id}" ${chosen?'checked':''}><img src="${escapeHtml(p.path)}" alt="${escapeHtml(p.alt)}" width="55" height="55" loading="lazy" decoding="async"><span><strong>${escapeHtml(s.city)}, ${escapeHtml(s.state)}</strong><small>${escapeHtml(s.name)}</small><span class="ops-picker-caption">${p.kind==='illustration'?'Illustration':'Location photo'} · AFDC ${s.id}</span></span><span>${s.ports} ports</span></label>`;}).join(''):'<div class="empty-state">No matching stations. Try another city, state or station ID.</div>';
};
const opsZones=['America/New_York','America/Chicago','America/Denver','America/Los_Angeles','America/Phoenix','Pacific/Honolulu'];
// RFC 5545 folds by UTF-8 octets, including when the sample calendar text is Russian.
function opsCalendarFold(text){const encoder=new TextEncoder();return text.split('\r\n').map(row=>{let output='',length=0;for(const char of row){const size=encoder.encode(char).length;if(length+size>75){output+='\r\n ';length=1;}output+=char;length+=size;}return output;}).join('\r\n');}
const opsZoneLabels={'America/New_York':'Eastern Time · New York','America/Chicago':'Central Time · Chicago','America/Denver':'Mountain Time · Denver','America/Los_Angeles':'Pacific Time · Los Angeles','America/Phoenix':'Arizona · Phoenix','Pacific/Honolulu':'Hawaii · Honolulu'};
const opsToday=(zone=Intl.DateTimeFormat().resolvedOptions().timeZone)=>new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function opsInstant(date,time,zone){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:\d{2}$/.test(time)||!opsZones.includes(zone))return null;
  const anchor=Date.parse(date+'T'+time+':00Z');if(!Number.isFinite(anchor))return null;
  const format=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
  const matches=[];
  for(let offset=-14*60;offset<=14*60;offset+=15){const value=anchor+offset*60000,p=Object.fromEntries(format.formatToParts(value).map(p=>[p.type,p.value]));if(`${p.year}-${p.month}-${p.day}`===date&&`${p.hour}:${p.minute}`===time)matches.push(value);}
  return matches.length===1?new Date(matches[0]).toISOString():null;
}
function opsAppointmentLabel(a){if(!a)return '';const instant=a.instant||opsInstant(a.date,a.time,a.timeZone);return instant?new Intl.DateTimeFormat('en-US',{timeZone:a.timeZone,weekday:'short',year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(instant)):`${a.date} at ${a.time} · ${opsZoneLabels[a.timeZone]||a.timeZone}`;}
function opsCallbackValid(a){const instant=opsInstant(a.date,a.time,a.timeZone);return instant&&Date.parse(instant)>Date.now()?instant:null;}
window.EcoChargeCallback={today:opsToday,validate:opsCallbackValid};
const opsService=t=>t.service||{};
const opsLastDate=t=>threadMessages(t).at(-1)?.date||t.repliedAt||t.date;
const opsClosed=t=>opsService(t).closed===true;
function opsTicketStatus(t){if(opsClosed(t))return 'Closed';if(t.callback?.status==='proposed')return 'Time proposed';if(t.callback?.status==='confirmed')return 'Demo time agreed';return t.status==='Open'?'Needs reply':'Answered';}
function opsNeedsWork(t){const s=opsService(t);return !opsClosed(t)&&(t.status==='Open'||(s.nextAction&&!s.done));}
function opsSortedTickets(){return demo.tickets.slice().sort((a,b)=>Number(opsNeedsWork(b))-Number(opsNeedsWork(a))||Number(opsService(b).priority==='high')-Number(opsService(a).priority==='high')||(opsService(a).due||'9999').localeCompare(opsService(b).due||'9999')||Date.parse(opsLastDate(b))-Date.parse(opsLastDate(a)));}
function opsTicketCard(t){const s=opsService(t),due=s.due&&s.nextAction&&!s.done;return `<article class="ticket-row ops-ticket"><div class="ticket-heading"><strong>${escapeHtml(t.subject)}</strong><span class="pill ${opsNeedsWork(t)?'pending':''}">${opsTicketStatus(t)}</span></div><small>${escapeHtml(demo.client.name)} · ${contactDate(t.date)}${s.priority==='high'?' · High priority':''}</small>${contextMarkup(t.context)}<p>${escapeHtml((threadMessages(t).filter(m=>m.from==='client').at(-1)?.text||t.message||'Manager started this conversation.'))}</p>${t.callback||t.appointment?`<div class="ops-appointment-label">${icon('calendar')}<span>${t.callback?'Demo appointment: ':'Requested: '}${escapeHtml(opsAppointmentLabel(t.callback||t.appointment))}</span></div>`:''}${s.nextAction?`<div class="ops-next-action"><strong>${s.done?'Completed follow-up':'Next action'}</strong><span>${escapeHtml(s.nextAction)}</span>${due?`<time class="${s.due<opsToday()?'ops-overdue':''}">${s.due<opsToday()?'Overdue · ':''}${escapeHtml(s.due)}</time>`:''}</div>`:''}<div class="ticket-actions"><button class="button secondary" data-reply="${escapeHtml(t.id)}">${t.reply?'Open conversation':'Reply to client'}</button><button class="text-button" data-ops-ticket="${escapeHtml(t.id)}">Notes & follow-up</button></div></article>`;}
function opsFilteredTickets(){return opsSortedTickets().filter(t=>(inboxFilter==='all'||inboxFilter==='open'&&opsNeedsWork(t)||inboxFilter==='replied'&&t.status!=='Open'&&!opsClosed(t)||inboxFilter==='callbacks'&&Boolean(t.appointment||t.callback)||inboxFilter==='closed'&&opsClosed(t))&&`${t.subject} ${t.message} ${t.reply} ${t.context?.stationName||''} ${t.context?.plan||''}`.toLowerCase().includes(opsInboxQuery));}
supportTable=function(){const rows=opsFilteredTickets();return `<section class="panel admin-section" id="manager-inbox"><div class="section-heading"><h2>${icon('chat')} Client conversations</h2><span>${demo.tickets.length} total</span></div><label class="ops-search-label" for="ops-inbox-search">Find a conversation</label><input id="ops-inbox-search" class="admin-search" type="search" value="${escapeHtml(opsInboxQuery)}" placeholder="Topic, message or station…"><div class="inbox-filters">${[['all','All'],['open','Needs attention'],['replied','Answered'],['callbacks','Calls'],['closed','Closed']].map(([id,label])=>`<button data-inbox-filter="${id}" aria-pressed="${inboxFilter===id}">${label}</button>`).join('')}</div><div id="ops-ticket-list">${rows.length?rows.map(opsTicketCard).join(''):'<div class="empty-state">No conversations match this view.</div>'}</div><button class="button secondary contextual-contact" data-action="manager-compose">${icon('mail')} Start a client conversation</button></section>`;};
function opsQueue(){const tickets=opsSortedTickets().filter(opsNeedsWork),pending=demo.requests.filter(r=>r.status==='Pending');return `<section class="panel ops-queue"><div class="ops-queue-heading"><div><span class="j-eyebrow">YOUR NEXT ACTIONS</span><h2>${tickets.length+pending.length?'Keep the client moving forward.':'Your queue is clear.'}</h2><p>${tickets.length} conversations need attention · ${pending.length} demo money requests</p></div><button class="button secondary" data-manager-view="requests">Open inbox ${icon('arrow')}</button></div><div class="ops-queue-list">${tickets.slice(0,3).map(t=>`<button data-reply="${escapeHtml(t.id)}"><span class="ops-queue-icon">${icon(t.appointment?'calendar':'chat')}</span><span><strong>${escapeHtml(t.subject)}</strong><small>${escapeHtml(opsService(t).nextAction||t.context?.plan||'Review the question and its context')}</small></span><b>${opsService(t).priority==='high'?'High priority':opsTicketStatus(t)}</b>${icon('arrow')}</button>`).join('')}${!tickets.length&&!pending.length?'<p>New questions and requests from the client demo will appear here. Replies stay in this browser.</p>':''}</div></section>`;}
function opsClientContext(){const p=demo.planDraft||demo.plan,source=demo.attribution;return `<section class="panel ops-context"><h2>Client context</h2><dl><div><dt>Plan being considered</dt><dd>${p?escapeHtml(p.name)+' · '+money(p.capital):'No saved plan'}</dd></div><div><dt>Saved locations</dt><dd>${demo.exploration?.saved?.length||0}</dd></div><div><dt>Last conversation</dt><dd>${demo.tickets.length?contactDate(new Date(Math.max(...demo.tickets.map(t=>Date.parse(opsLastDate(t))))).toISOString()):'No conversation yet'}</dd></div><div><dt>First-touch source</dt><dd>${escapeHtml(source?.utm_source||'Not recorded')}</dd></div>${source?.utm_campaign?`<div><dt>Campaign</dt><dd>${escapeHtml(source.utm_campaign)}</dd></div>`:''}</dl><p>Local demo profile. No external CRM or live support delivery.</p></section>`;}
function opsManageTicket(id){if(role!=='admin')return;const t=demo.tickets.find(t=>t.id===id);if(!t)return;const s=opsService(t);openModal(`<span class="j-eyebrow">STAFF FOLLOW-UP</span><h2>${escapeHtml(t.subject)}</h2>${contextMarkup(t.context)}<form id="ops-ticket-form" data-ticket="${escapeHtml(id)}"><div class="ops-two-fields"><div><label for="ops-priority">Priority</label><select id="ops-priority"><option value="normal">Normal</option><option value="high" ${s.priority==='high'?'selected':''}>High</option></select></div><div><label for="ops-due">Follow-up date</label><input id="ops-due" type="date" value="${escapeHtml(s.due||'')}"></div></div><label for="ops-next">Next action</label><input id="ops-next" maxlength="180" value="${escapeHtml(s.nextAction||'')}" placeholder="Prepare an answer about access to funds"><label for="ops-note">Staff note</label><textarea id="ops-note" maxlength="1500" rows="4" placeholder="Context for the next conversation">${escapeHtml(s.note||'')}</textarea><label class="ops-check"><input id="ops-done" type="checkbox" ${s.done?'checked':''}> Follow-up completed</label><label class="ops-check"><input id="ops-closed" type="checkbox" ${s.closed?'checked':''}> Close this conversation</label><p class="form-hint">Notes are shown only in the staff interface. This browser-only demo does not provide secure private storage or scheduled reminders. A new client message reopens the conversation.</p><div class="form-error" role="alert"></div><button class="button primary" type="submit">Save follow-up</button></form>${t.appointment||t.callback?`<button class="button secondary" data-ops-schedule="${escapeHtml(id)}">Propose a demo call time</button>`:''}`);}
function opsSchedule(id){if(role!=='admin')return;const t=demo.tickets.find(t=>t.id===id);if(!t)return;const a=t.callback||t.appointment||{date:opsToday('America/New_York'),time:'14:00',timeZone:'America/New_York'};openModal(`<span class="j-eyebrow">DEMO APPOINTMENT</span><h2>Suggest a time to the client.</h2><p>The client can accept the suggestion in the demo inbox. No live meeting or invitation is sent.</p><form id="ops-schedule-form" data-ticket="${escapeHtml(id)}"><div class="ops-two-fields"><div><label for="ops-call-date">Date</label><input id="ops-call-date" type="date" value="${escapeHtml(a.date)}" required></div><div><label for="ops-call-time">Time</label><input id="ops-call-time" type="time" value="${escapeHtml(a.time)}" required></div></div><label for="ops-call-zone">Client time zone</label><select id="ops-call-zone">${opsZones.map(z=>`<option value="${z}" ${z===a.timeZone?'selected':''}>${opsZoneLabels[z]}</option>`).join('')}</select><div class="form-error" role="alert"></div><button class="button primary" type="submit">Suggest demo time</button></form>`);}
function opsReplyMessage(t,text){const now=new Date().toISOString();t.messages=threadMessages(t);t.messages.push({from:'manager',text,date:now});t.reply=text;t.readReply=null;t.repliedAt=now;t.status='Resolved';t.service={...opsService(t),closed:false};}
function opsAppointmentMarkup(t){const a=t.callback;if(!a)return '';const passed=Date.parse(a.instant)<=Date.now(),when=new Date(a.instant),dateLabel=new Intl.DateTimeFormat('en-US',{timeZone:a.timeZone,weekday:'short',month:'short',day:'numeric',year:'numeric'}).format(when),timeLabel=new Intl.DateTimeFormat('en-US',{timeZone:a.timeZone,hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(when);return `<section class="ops-call-card"><span class="j-eyebrow">${a.status==='confirmed'?'AGREED IN DEMO':a.status==='cancelled'?'CANCELLED IN DEMO':'SUGGESTED DEMO TIME'}</span><h3>${escapeHtml(dateLabel)}</h3><p>${escapeHtml(timeLabel)} · 20 minutes</p><p>${escapeHtml(opsZoneLabels[a.timeZone])}</p><small>No live call is booked. This is a scheduling demonstration.</small><div>${a.status==='proposed'&&!passed?`<button class="button primary" data-ops-accept="${escapeHtml(t.id)}">Accept demo time</button>`:''}${a.status==='confirmed'&&!passed?`<button class="button secondary" data-ops-calendar="${escapeHtml(t.id)}">Download sample calendar event</button>`:''}${a.status!=='cancelled'?`<button class="text-button" data-ops-cancel="${escapeHtml(t.id)}">Cancel demo appointment</button>`:''}</div>${passed&&a.status!=='cancelled'?'<p>This time has passed. Ask your manager to suggest another.</p>':''}</section>`;}
const opsShowThreadBefore=showThread;
showThread=function(id){opsShowThreadBefore(id);const t=demo.tickets.find(t=>t.id===id);if(t?.callback)$('#followup-form').insertAdjacentHTML('beforebegin',opsAppointmentMarkup(t));};

// Restore unsent text after navigation without generating a message or an event.
const opsDraftKey='ecocharge-message-drafts-v1';
function opsReadDrafts(){try{const value=JSON.parse(localStorage.getItem(opsDraftKey)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch{return {};}}
function opsDraftId(form){return [role,form.id,form.dataset.ticket||form.querySelector('#contact-topic')?.value||'new',JSON.stringify(form._context||{})].join('|');}
const opsDraftFields=form=>[...form.querySelectorAll('textarea,input:not([type=hidden]),select')].filter(el=>el.id);
function opsSaveDraft(form){const data=opsReadDrafts(),fields={};opsDraftFields(form).forEach(el=>fields[el.id]=el.value.slice(0,1500));data[opsDraftId(form)]={at:Date.now(),fields};const newest=Object.entries(data).sort((a,b)=>b[1].at-a[1].at).slice(0,20);try{localStorage.setItem(opsDraftKey,JSON.stringify(Object.fromEntries(newest)));form.querySelector('.ops-draft-hint').textContent='Draft saved in this browser.';}catch{}}
function opsClearDraft(form){const data=opsReadDrafts();delete data[opsDraftId(form)];try{localStorage.setItem(opsDraftKey,JSON.stringify(data));}catch{}}
window.EcoChargeDrafts={clear:opsClearDraft};
const opsReplySnippets={rights:'The demo does not create investment rights. The legal issuer, client instrument and ownership evidence still need final documentation. I can walk you through the open questions.',rates:'The weekly percentages are demo assumptions, not verified station returns. The operating example explains receipts and costs, but does not establish a client payout.',access:'The fees, holding period and capital-access conditions are not finalized. No real funds can be deposited or withdrawn here. We can review the questions the final terms must answer.'};
function opsEnhanceComposer(){const form=$('#modal form');if(!form||!['support-form','followup-form','reply-form','manager-message-form'].includes(form.id)||form.dataset.opsEnhanced)return;form.dataset.opsEnhanced='true';const saved=opsReadDrafts()[opsDraftId(form)];if(saved&&Date.now()-saved.at<30*864e5)opsDraftFields(form).forEach(el=>{if(typeof saved.fields?.[el.id]==='string')el.value=saved.fields[el.id];});if(form.querySelector('#callback-zone'))$('#callback-date').min=opsToday($('#callback-zone').value);form.insertAdjacentHTML('beforeend',`<p class="ops-draft-hint" role="status">${saved?'Unsent draft restored.':'Unsent text stays in this browser.'}</p>`);if(form.id==='reply-form'){const t=demo.tickets.find(t=>t.id===form.dataset.ticket);form.insertAdjacentHTML('afterbegin',`<div class="ops-reply-tools"><span>Insert a draft answer</span>${[['rights','Rights'],['rates','Calculation'],['access','Fees & access']].map(([id,label])=>`<button type="button" data-ops-snippet="${id}">${label}</button>`).join('')}</div>`);form.querySelector('[type=submit]').textContent='Send demo reply';if(t)form.insertAdjacentHTML('afterend',`<div class="ops-thread-tools"><button class="text-button" data-ops-ticket="${escapeHtml(t.id)}">Staff notes & next action</button>${t.appointment||t.callback?`<button class="text-button" data-ops-schedule="${escapeHtml(t.id)}">Suggest a demo call time</button>`:''}</div>`);}}
const opsModalBefore=openModal;
openModal=function(html){opsModalBefore(html);queueMicrotask(opsEnhanceComposer);};
const opsAdminBefore=renderAdmin;
renderAdmin=function(){opsAdminBefore();if(workspaceRole!=='admin')return;const main=$('#admin-view .manager-layout>div');if(adminTab==='overview'&&main){main.insertAdjacentHTML('afterbegin',opsQueue());main.querySelector('#manager-inbox')?.remove();}if(['overview','clients','requests'].includes(adminTab))$('#admin-view .manager-layout>aside')?.insertAdjacentHTML('afterbegin',opsClientContext());};
activityPanel=function(){const rows=demo.activity.slice(0,8),row=a=>`<div class="activity-row">${escapeHtml(a.text)}<small>${contactDate(a.date)}</small></div>`;return `<section class="panel admin-section ops-activity"><h2>${icon('calendar')} Recent changes</h2>${rows.length?rows.slice(0,2).map(row).join(''):'<p class="form-hint">Your demo actions will appear here.</p>'}${rows.length>2?`<details><summary>Show ${rows.length-2} earlier entries</summary>${rows.slice(2).map(row).join('')}</details>`:''}</section><div class="notice"><span>ⓘ</span><p>Separate demo accounts.<br>Changes sync between tabs in this browser.</p></div>`;};
const opsResetBefore=actions['confirm-reset'];
actions['confirm-reset']=()=>{if(role!=='admin'){opsResetBefore();return;}opsInboxQuery='';opsResetBefore();try{localStorage.removeItem(opsDraftKey);sessionStorage.removeItem('ecocharge-working-plan');sessionStorage.removeItem('ecocharge-plan-review');}catch{}};

document.addEventListener('input',e=>{if(e.target.id==='ops-inbox-search'){opsInboxQuery=e.target.value.toLowerCase().trim();const rows=opsFilteredTickets();$('#ops-ticket-list').innerHTML=rows.length?rows.map(opsTicketCard).join(''):'<div class="empty-state">No conversations match this search.</div>';}const form=e.target.closest('form[data-ops-enhanced]');if(form)opsSaveDraft(form);});
document.addEventListener('change',e=>{const form=e.target.closest('form[data-ops-enhanced]');if(form)opsSaveDraft(form);if(e.target.id==='callback-zone')$('#callback-date').min=opsToday(e.target.value);});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
  if(b.dataset.opsTicket)opsManageTicket(b.dataset.opsTicket);
  if(b.dataset.opsSchedule)opsSchedule(b.dataset.opsSchedule);
  if(b.dataset.opsSnippet&&role==='admin'){const field=$('#reply-text');const next=field.value+(field.value.trim()?'\n\n':'')+(window.EcoLocale?.t(opsReplySnippets[b.dataset.opsSnippet])||opsReplySnippets[b.dataset.opsSnippet]);if(next.length>1500){toast('Shorten the draft before inserting another answer.');return;}field.value=next;field.dispatchEvent(new Event('input',{bubbles:true}));field.focus();}
  const id=b.dataset.opsAccept||b.dataset.opsCancel||b.dataset.opsCalendar;if(!id||role!=='client')return;const t=demo.tickets.find(t=>t.id===id),a=t?.callback;if(!a)return;
  if(b.dataset.opsCalendar&&a.status==='confirmed'){const stamp=d=>new Date(d).toISOString().replaceAll('-','').replaceAll(':','').split('.')[0]+'Z',text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//EcoCharge//Demo//EN','BEGIN:VEVENT','UID:'+t.id+'@ecocharge-demo','DTSTAMP:'+stamp(Date.now()),'DTSTART:'+stamp(a.instant),'DTEND:'+stamp(Date.parse(a.instant)+20*60000),window.EcoLocale?.language==='ru'?'SUMMARY:EcoCharge — тестовая встреча':'SUMMARY:EcoCharge demo walkthrough (sample)',window.EcoLocale?.language==='ru'?'DESCRIPTION:Демонстрация планирования. Реальный звонок не назначен.':'DESCRIPTION:Local scheduling demonstration. No live call is booked.','END:VEVENT','END:VCALENDAR',''].join('\r\n');const url=URL.createObjectURL(new Blob([opsCalendarFold(text)],{type:'text/calendar;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='ecocharge-demo-appointment.ics';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(b.dataset.opsAccept&&(a.status!=='proposed'||Date.parse(a.instant)<=Date.now())){toast('Ask the manager to suggest a future demo time.');return;}
  a.status=b.dataset.opsAccept?'confirmed':'cancelled';const now=new Date().toISOString(),message=b.dataset.opsAccept?'I accepted the suggested time in the demo. No live call is booked.':'I cancelled this demo appointment.',text=window.EcoLocale?.t(message)||message;t.messages=threadMessages(t);t.messages.push({from:'client',text,date:now});t.message=text;t.status='Open';t.service={...opsService(t),closed:false};persist();showThread(t.id);toast(b.dataset.opsAccept?'Demo time accepted.':'Demo appointment cancelled.');
});
document.addEventListener('submit',e=>{const form=e.target;if(!['ops-ticket-form','ops-schedule-form'].includes(form.id))return;e.preventDefault();if(role!=='admin')return;const t=demo.tickets.find(t=>t.id===form.dataset.ticket);if(!t)return;
  if(form.id==='ops-ticket-form'){
    const nextAction=$('#ops-next').value.trim(),due=$('#ops-due').value;if(due&&!nextAction){form.querySelector('.form-error').textContent='Add a next action for this follow-up date.';return;}
    t.service={priority:$('#ops-priority').value,due,nextAction,note:$('#ops-note').value.trim(),done:$('#ops-done').checked,closed:$('#ops-closed').checked,updatedAt:new Date().toISOString()};if(t.service.closed)t.status='Resolved';activity('Staff updated follow-up for '+t.id);persist();$('#modal').close();renderAdmin();toast('Staff follow-up saved. No reminder or client message was sent.');
  }else{
    const a={date:$('#ops-call-date').value,time:$('#ops-call-time').value,timeZone:$('#ops-call-zone').value},instant=opsCallbackValid(a);if(!instant){form.querySelector('.form-error').textContent='Choose a future time in the selected time zone. Avoid an unavailable or repeated daylight-saving time.';return;}
    t.callback={...a,instant,status:'proposed'};opsReplyMessage(t,window.EcoLocale?.language==='ru'?'Предлагаю время для знакомства с демо: '+window.EcoLocale.t(opsAppointmentLabel(a))+'. Подтвердите или предложите другое время в переписке. Реальный звонок не назначен.':'Suggested demo walkthrough: '+opsAppointmentLabel(a)+'. Please accept or ask for another time in this conversation. No live call is booked.');activity('Staff suggested a demo appointment');persist();$('#modal').close();renderAdmin();toast('Demo time suggested in the client inbox.');
  }
});
